30	#include <tvm/tirx/analysis.h>
31	#include <tvm/tirx/builtin.h>
32	#include <tvm/tirx/expr.h>
33	#include <tvm/tirx/op.h>
34	#include <tvm/tirx/stmt_functor.h>
35	#include <tvm/tirx/transform.h>
36	
37	#include <unordered_set>
38	
39	#include "../op/builtin.h"
40	#include "common/assume.h"
41	#include "common/attr.h"
42	#include "tir/analysis/var_use_def_analysis.h"
43	#include <tvm/tirx/stmt.h>
44	
45	namespace tvm {
46	namespace tl {
47	using namespace ffi;
48	using namespace tirx;
49	
50	// This pass traverses the AST, split the target function into host part and
51	// device part and copies all assume attribute statements to the device side.
52	
53	// 1. Traverse AST and collect all assume statements into host_assumes_.
54	// 2. Until the first AttrStmtNode with tvm::attr::kTarget.
55	// 3. Call SplitDeviceFunc, which will create a new device function and replace
56	//    the original body with a call to that function.
57	class HostDeviceSplitter : public tirx::StmtMutator {
58	public:
59	  explicit HostDeviceSplitter(IRModule *device_mod,
60	                              std::function<GlobalVar()> var_supply)
61	      : device_mod_(device_mod), var_supply_(std::move(var_supply)) {}
62	
63	  void SetNonRestrictParams(const Array<tirx::Var> &params) {
64	    for (auto param : params) {
65	      non_restrict_params_.push_back(param);
66	    }
67	  }
68	
69	  void SetClusterDims(Array<Integer> cluster_dims) {
70	    cluster_dims_ = std::move(cluster_dims);
71	  }
72	
73	  void SetSmemAlignmentMap(Map<String, IntImm> smem_alignment_map) {
74	    smem_alignment_map_ = std::move(smem_alignment_map);
75	  }
76	
77	  void SetHostFuncSignature(const tirx::PrimFunc &func) {
78	    host_buffer_map_ = func->buffer_map;
79	  }
80	
81	  tirx::Stmt VisitStmt_(const tirx::AttrStmtNode *op) final {
82	    if (op->attr_key == tvm::attr::kTarget) {
83	      found_device_region_ = true;
84	      auto device_target = op->node.as<tvm::Target>().value().WithoutHost();
85	      return SplitDeviceFunc(op->body, device_target);
86	    } else if (op->attr_key == tirx::attr::tilelang_assume) {
87	      // NOTE(chaofan): the assumes collected here must be in host-side.
88	      //    This is because when the collector reaches the split region,
89	      //    it will start to split and return. For safety, we add a check here.
90	      ICHECK(!found_device_region_)
91	          << "Assumes collection should not be in device region.";
92	      // We first push back the outside assume, then visit the child.
93	      // So when moving assumes to device side, we need to do the building
94	      // process in a reverse order.
95	      host_assumes_.push_back(op);
96	    }
97	    return tirx::StmtMutator::VisitStmt_(op);
98	  }
99	
100	  tirx::Stmt VisitStmt_(const tirx::EvaluateNode *op) final {
101	    auto stmt = GetRef<tirx::Stmt>(op);
102	    // There should be no assume in evaluate form after InjectAssumes.
103	    ICHECK(!IsAssumeInEvaluateForm(stmt))
104	        << "Unexpected assume in evaluate form. Please run InjectAssumes pass "
105	           "first.";
106	    return tirx::StmtMutator::VisitStmt_(op);
107	  }
108	
109	  tirx::Stmt ForceSplit(tirx::Stmt body, tvm::Target device_target) {
110	    return SplitDeviceFunc(std::move(body), std::move(device_target));
111	  }
112	
113	  bool found_device_region() const { return found_device_region_; }
114	
115	private:
116	  bool found_device_region_{false};
117	  Map<tirx::Var, tirx::Buffer> host_buffer_map_;
118	  Array<tirx::Var> non_restrict_params_;
119	  Optional<Array<Integer>> cluster_dims_{std::nullopt};
120	  // Per-buffer shared-memory alignment requirements (kSmemAlignmentMap)
121	  // propagated from the host PrimFunc onto each split device kernel.
122	  Map<String, IntImm> smem_alignment_map_;
123	  Optional<String> code_block_source_{std::nullopt};
124	  Optional<String> code_block_entry_name_{std::nullopt};
125	
126	  static void SortDeviceParams(std::vector<tirx::Var> *params) {
127	    std::sort(params->begin(), params->end(),
128	              [](const tirx::Var &a, const tirx::Var &b) {
129	                auto sort_key = [](const tirx::Var &var) {
130	                  return std::tuple{
131	                      !var->dtype.is_handle(),
132	                      var->name_hint,
133	                  };
134	                };
135	                return sort_key(a) < sort_key(b);
136	              });
137	  }
138	
139	  std::tuple<Array<tirx::Var>, Array<tirx::Buffer>>
140	  CollectSourceKernelSignature() const {
141	    std::vector<tirx::Var> params;
142	    std::unordered_set<std::string> seen_vars;
143	
144	    auto push = [&](const tirx::Var &var) {
145	      if (var.defined() && seen_vars.insert(var->name_hint).second) {
146	        params.push_back(var);
147	      }
148	    };
149	
150	    Array<tirx::Buffer> buffers_to_declare;
151	    for (const auto &kv : host_buffer_map_) {
152	      const tirx::Buffer &buf = kv.second;
153	      push(buf->data);
154	      buffers_to_declare.push_back(buf);
155	      for (const PrimExpr &dim : buf->shape) {
156	        if (const auto *var = dim.as<tirx::VarNode>()) {
157	          push(GetRef<tirx::Var>(var));
158	        }
159	      }
160	      for (const PrimExpr &stride : buf->strides) {
161	        if (const auto *var = stride.as<tirx::VarNode>()) {
162	          push(GetRef<tirx::Var>(var));
163	        }
164	      }
165	      if (const auto *var = buf->elem_offset.as<tirx::VarNode>()) {
166	        push(GetRef<tirx::Var>(var));
167	      }
168	    }
169	
170	    SortDeviceParams(&params);
171	    return {Array<tirx::Var>(params.begin(), params.end()), buffers_to_declare};
172	  }
173	
174	  class SourceKernelAttrExtractor : public tirx::StmtMutator {
175	  public:
176	    static Stmt Extract(Stmt body, Optional<String> *code_block_source,
177	                        Optional<String> *code_block_entry_name) {
178	      SourceKernelAttrExtractor extractor(code_block_source,
179	                                          code_block_entry_name);
180	      return extractor(std::move(body));
181	    }
182	
183	  private:
184	    explicit SourceKernelAttrExtractor(Optional<String> *code_block_source,
185	                                       Optional<String> *code_block_entry_name)
186	        : code_block_source_(code_block_source),
187	          code_block_entry_name_(code_block_entry_name) {}
188	
189	    Stmt VisitStmt_(const tirx::AttrStmtNode *op) final {
190	      if (op->attr_key == tl::attr::kCodeBlockSource) {
191	        if (auto str = op->value.as<StringImmNode>()) {
192	          *code_block_source_ = str->value;
193	        } else {
194	          LOG(FATAL) << "Expected `" << tl::attr::kCodeBlockSource
195	                     << "` AttrStmt to carry a StringImm value, but got "
196	                     << op->value->GetTypeKey();
197	        }
198	        return VisitStmt(op->body);
199	      }
200	
201	      if (op->attr_key == tl::attr::kCodeBlockEntryName) {
202	        if (auto str = op->value.as<StringImmNode>()) {
203	          *code_block_entry_name_ = str->value;
204	        } else {
205	          LOG(FATAL) << "Expected `" << tl::attr::kCodeBlockEntryName
206	                     << "` AttrStmt to carry a StringImm value, but got "
207	                     << op->value->GetTypeKey();
208	        }
209	        return VisitStmt(op->body);
210	      }
211	
212	      return tirx::StmtMutator::VisitStmt_(op);
213	    }
214	
215	    Optional<String> *code_block_source_;
216	    Optional<String> *code_block_entry_name_;
217	  };
218	
219	  class BufferUseRemapper : public tirx::StmtExprMutator {
220	  public:
221	    explicit BufferUseRemapper(Map<tirx::Buffer, tirx::Buffer> buffer_remap)
222	        : explicit_buffer_remap_(std::move(buffer_remap)) {}
223	
224	  private:
225	    tirx::Buffer VisitBufferUse(const tirx::Buffer &buffer) final {
226	      if (auto it = explicit_buffer_remap_.find(buffer);
227	          it != explicit_buffer_remap_.end()) {
228	        return (*it).second;
229	      }
230	      return tirx::StmtExprMutator::VisitBufferUse(buffer);
231	    }
232	
233	    Map<tirx::Buffer, tirx::Buffer> explicit_buffer_remap_;
234	  };
235	
236	  // Wrap body with assumes, substituting variables in assumes with the
237	  // corresponding variables in the device body based on name_hint matching.
238	  // This substitution is necessary because host-side assume variables may be
239	  // different Var objects from device-side parameters, even if they have the
240	  // same name. We always perform substitution to ensure ConvertSSA sees
241	  // consistent variable references.
242	  Stmt wrapBodyWithHostSideAssumes(
243	      Stmt body,
244	      const std::unordered_map<std::string, tirx::Var> &name_to_var) {
245	    // Build substitution map: assume_var -> body_var
246	    // Always substitute if we find a matching name, regardless of whether
247	    // it's the same object. This ensures ConvertSSA treats them as the same
248	    // variable.
249	    auto substitute_func =
250	        [&name_to_var](const tirx::Var &var) -> Optional<PrimExpr> {
251	      auto it = name_to_var.find(var->name_hint);
252	      if (it != name_to_var.end()) {
253	        return it->second;
254	      }
255	      return Optional<PrimExpr>();
256	    };
257	
258	    for (auto it = host_assumes_.rbegin(); it != host_assumes_.rend(); ++it) {
259	      // Substitute variables in the assume condition
260	      PrimExpr original_node = Downcast<PrimExpr>((*it)->node);
261	      PrimExpr substituted_node =
262	          tirx::Substitute(original_node, substitute_func);
263	      body = AttrStmt(substituted_node, tirx::attr::tilelang_assume,
264	                      (*it)->value, body);
265	    }
266	    return body;
267	  }
268	
269	  tirx::Stmt SplitDeviceFunc(tirx::Stmt body, tvm::Target device_target) {
270	    code_block_source_ = std::nullopt;
271	    code_block_entry_name_ = std::nullopt;
272	    body = SourceKernelAttrExtractor::Extract(
273	        std::move(body), &code_block_source_, &code_block_entry_name_);
274	
275	    // Normal kernels infer device parameters from use-def of the device body.
276	    // Source kernels have no meaningful DSL body, so their device signature
277	    // must be reconstructed explicitly from the host PrimFunc signature and
278	    // buffer metadata.
279	    auto [old_params, buffers_to_declare] =
280	        [&]() -> std::tuple<Array<tirx::Var>, Array<tirx::Buffer>> {
281	      if (code_block_source_) {
282	        return CollectSourceKernelSignature();
283	      }
284	
285	      tirx::VarUseDefAnalyzer use_def(/*defined_vars=*/{},
286	                                      /*visit_thread_extent=*/true);
287	      use_def(body);
288	
289	      std::vector<tirx::Var> params{use_def.undefined_.begin(),
290	                                    use_def.undefined_.end()};
291	      SortDeviceParams(&params);
292	      return {Array<tirx::Var>(params.begin(), params.end()),
293	              use_def.undefined_buffers_};
294	    }();
295	
296	    // Create new parameter variables for the device function to avoid sharing
297	    // Var objects with the host function. This prevents ConvertSSA from
298	    // incorrectly renaming variables when it processes multiple functions.
299	    Array<tirx::Var> params;
300	    Map<tirx::Var, PrimExpr> var_remap;
301	    std::unordered_map<std::string, tirx::Var> name_to_var;
302	    for (const auto &old_var : old_params) {
303	      tirx::Var new_var(old_var->name_hint, old_var->type_annotation);
304	      params.push_back(new_var);
305	      var_remap.Set(old_var, new_var);
306	      name_to_var[old_var->name_hint] = new_var;
307	    }
308	
309	    // Substitute old variables with new ones in the body
310	    body = tirx::Substitute(body, var_remap);
311	
312	    // Also remap buffers to use new variables
313	    Array<tirx::Buffer> new_buffers_to_declare;
314	    Map<tirx::Buffer, tirx::Buffer> buffer_remap;
315	    for (const auto &buf : buffers_to_declare) {
316	      auto new_shape = buf->shape.Map(
317	          [&](const PrimExpr &e) { return tirx::Substitute(e, var_remap); });
318	      auto new_strides = buf->strides.Map(
319	          [&](const PrimExpr &e) { return tirx::Substitute(e, var_remap); });
320	      auto new_elem_offset = tirx::Substitute(buf->elem_offset, var_remap);
321	      auto new_data = var_remap.count(buf->data)
322	                          ? Downcast<tirx::Var>(var_remap[buf->data])
323	                          : buf->data;
324	      tirx::Buffer new_buf(new_data, buf->dtype, new_shape, new_strides,
325	                           new_elem_offset, buf->name, buf->data_alignment,
326	                           buf->offset_factor, buf->buffer_type,
327	                           buf->axis_separators, buf->span);
328	      buffer_remap.Set(buf, new_buf);
329	      new_buffers_to_declare.push_back(new_buf);
330	    }
331	    body = BufferUseRemapper(buffer_remap)(std::move(body));
332	    buffers_to_declare = new_buffers_to_declare;
333	
334	    // CodeGenCPU is used for some device-side targets, such as
335	    // "ext_dev", and expects to be able to return a int32_t status
336	    // code.
337	
338	    bool can_propagate_errors = [&]() {
339	      auto kind = device_target->GetTargetDeviceType();
340	      return kind == kDLCPU || kind == kDLExtDev || kind == kDLHexagon;
341	    }();
342	    IntImm success(DataType::Int(32), 0);
343	    Type kernel_ret_type;
344	    if (can_propagate_errors) {
345	      kernel_ret_type = PrimType(DataType::Int(32));
346	      body = tirx::SeqStmt::Flatten(body, tirx::Evaluate(ret(success)));
347	    } else {
348	      kernel_ret_type = VoidType();
349	    }
350	
351	    // Declare necessary buffers for the device side.
352	    for (tirx::Buffer buf : buffers_to_declare) {
353	      body = tirx::SeqStmt({tirx::DeclBuffer(buf), std::move(body)});
354	    }
355	
356	    // Copy assumes from host-side to device-side, with variable substitution.
357	    // This must be done after DeclBuffer so that assumes are at the outermost
358	    // level of the function body. This ensures ConvertSSA correctly identifies
359	    // that assume variables refer to function parameters.
360	    body = wrapBodyWithHostSideAssumes(body, name_to_var);
361	
362	    // Remap non_restrict_params to use new parameter variables
363	    Array<tirx::Var> remapped_non_restrict_params;
364	    for (const auto &old_var : non_restrict_params_) {
365	      if (var_remap.count(old_var)) {
366	        remapped_non_restrict_params.push_back(
367	            Downcast<tirx::Var>(var_remap[old_var]));
368	      } else {
369	        remapped_non_restrict_params.push_back(old_var);
370	      }
371	    }
372	
373	    tirx::PrimFunc device_func(params, body, kernel_ret_type);
374	    Map<String, Any> device_attrs = {
375	        {tvm::attr::kTarget, device_target},
376	        {tirx::attr::kNoAlias, true},
377	        {tirx::attr::kIsGlobalFunc, true},
378	        {tl::attr::kNonRestrictParams, remapped_non_restrict_params}};
379	    if (cluster_dims_.defined()) {
380	      device_attrs.Set("cluster_dims", cluster_dims_.value());
381	    }
382	    if (!smem_alignment_map_.empty()) {
383	      device_attrs.Set(tl::kSmemAlignmentMap, smem_alignment_map_);
384	    }
385	    if (code_block_source_) {
386	      device_attrs.Set(tl::attr::kCodeBlockSource, code_block_source_.value());
387	    }
388	    device_func = WithAttrs(std::move(device_func), device_attrs);
389	
390	    GlobalVar kernel_symbol_global = var_supply_();
391	    if (code_block_entry_name_) {
392	      kernel_symbol_global = GlobalVar(code_block_entry_name_.value());
393	    }
394	
395	    (*device_mod_)->Add(kernel_symbol_global, device_func);
396	    // Use old_params as call arguments (host-side variables)
397	    Array<PrimExpr> args =
398	        old_params.Map([](const tirx::Var &var) -> PrimExpr { return var; });
399	
400	    if (can_propagate_errors) {
401	      tirx::Var kernel_error_code("kernel_error_code", success->dtype);
402	      tirx::Call kernel_call(success->dtype, kernel_symbol_global, args);
403	      tirx::Stmt assert_success = tirx::AssertStmt(
404	          kernel_error_code == success, tirx::StringImm("RuntimeError"),
405	          Array<tirx::StringImm>(
406	              {tirx::StringImm("Error executing compute kernel")}));
407	      tirx::Stmt let_check = tirx::SeqStmt(
408	          {tirx::Bind(kernel_error_code, kernel_call), assert_success});
409	
410	      return let_check;
411	
412	    } else {
413	      return tirx::Evaluate(
414	          tirx::Call(DataType::Void(), kernel_symbol_global, args));
415	    }
416	  }
417	
418	  // target ir module
419	  IRModule *device_mod_;
420	  // Generate new GlobalVar for the kernel
421	  std::function<GlobalVar()> var_supply_;
422	  // Collect assumes in host side
423	  Array<const tirx::AttrStmtNode *> host_assumes_;
424	};
425	
426	tirx::PrimFunc SplitHostDevice(tirx::PrimFunc func, IRModule *device_mod,
427	                               std::function<GlobalVar()> var_supply) {
428	  HostDeviceSplitter splitter(device_mod, std::move(var_supply));
429	  splitter.SetHostFuncSignature(func);
430	  // Propagate non-restrict parameter list from host func to device kernels
431	  if (auto opt =
432	          func->GetAttr<Array<tirx::Var>>(tl::attr::kNonRestrictParams)) {
433	    splitter.SetNonRestrictParams(opt.value());
434	    // Remove the attribute from host-side PrimFunc; it only matters for device
435	    // codegen.
436	    func = tvm::WithoutAttr(std::move(func), tl::attr::kNonRestrictParams);
437	  }
438	  // Propagate cluster_dims from host func to device kernel.
439	  // LowerOpaqueBlock sets this attr on the pre-split kernel; after splitting
440	  // it must live on the device side so the codegen can emit a cluster launch.
441	  if (auto opt = func->GetAttr<Array<Integer>>("cluster_dims")) {
442	    splitter.SetClusterDims(opt.value());
443	    func = tvm::WithoutAttr(std::move(func), "cluster_dims");
444	  }
445	  // Propagate per-buffer shared-memory alignment requirements collected by
446	  // LowerTileOp onto the device kernel, where MergeSharedMemoryAllocations
447	  // consumes them.
448	  if (auto opt = func->GetAttr<Map<String, IntImm>>(tl::kSmemAlignmentMap)) {
449	    splitter.SetSmemAlignmentMap(opt.value());
450	    func = tvm::WithoutAttr(std::move(func), tl::kSmemAlignmentMap);
451	  }
452	
453	  if (auto body = splitter(func->body); !body.same_as(func->body)) {
454	    func.CopyOnWrite()->body = body;
455	  } else if (!splitter.found_device_region()) {
456	    if (auto target = func->GetAttr<Target>(tvm::attr::kTarget)) {
457	      auto device_target = target.value().WithoutHost();
458	      if (device_target.defined() &&
459	          func->HasNonzeroAttr(tirx::attr::kIsEntryFunc) &&
460	          tirx::is_no_op(func->body)) {
461	        if (auto forced = splitter.ForceSplit(func->body, device_target);
462	            !forced.same_as(func->body)) {
463	          func.CopyOnWrite()->body = forced;
464	        }
465	      }
466	    }
467	  }
468	  return func;
469	}
470	
471	namespace transform {
472	
473	tvm::transform::Pass SplitHostDevice() {
474	  auto pass_func = [](IRModule mod, tvm::transform::PassContext ctx) {
475	    tvm::GlobalVarSupply global_var_supply(mod);
476	
477	    IRModule device_mod = IRModule(Map<GlobalVar, BaseFunc>({}));
478	    IRModule updates = IRModule(Map<GlobalVar, BaseFunc>({}));
479	
480	    for (const auto &[gvar, base_func] : mod->functions) {
481	      if (auto opt = base_func.as<tirx::PrimFunc>()) {
482	        tirx::PrimFunc func = opt.value();
483	
484	        auto global_symbol = func->GetAttr<String>(tvm::attr::kGlobalSymbol);
485	        auto name_prefix = global_symbol.value_or(gvar->name_hint);
486	        auto kernel_name = name_prefix + "_kernel";
487	        auto var_supply = [&global_var_supply, &kernel_name]() -> GlobalVar {
488	          return global_var_supply->FreshGlobal(kernel_name, false);
489	        };
490	
491	        func = ::tvm::tl::SplitHostDevice(std::move(func), &device_mod,
492	                                          var_supply);
493	        if (!func.same_as(base_func)) {
494	          updates->Add(gvar, func);
495	        }
496	      }
497	    }
498	    mod->Update(updates);
499	    mod->Update(device_mod);
500	    return tirx::transform::ConvertSSA()(mod);
501	  };
502	
503	  return tvm::transform::CreateModulePass(pass_func, 0, "tl.SplitHostDevice",
504	                                          {});
505	}
506	
507	TVM_FFI_STATIC_INIT_BLOCK() {
508	  namespace refl = reflection;
509	  refl::GlobalDef().def("tl.transform.SplitHostDevice", SplitHostDevice);
510	}
511	
512	} // namespace transform
513	} // namespace tl
514	} // namespace tvm
