43	static Buffer makeBufferWithLayout(const Buffer &buffer, const Layout &layout,
44	                                   Map<Var, Var> &var_remap) {
45	  const auto *ptr_type =
46	      TVM_TYPE_AS(buffer->data->type_annotation, PointerTypeNode);
47	  Type new_type;
48	  // convert fragments to normal local buffer
49	  if (IsFragmentBuffer(buffer)) {
50	    new_type = PointerType(ptr_type->element_type, "local");
51	  } else {
52	    new_type = buffer->data->type_annotation;
53	  }
54	  Var new_var;
55	  if (IsGlobalBuffer(buffer)) {
56	    new_var = buffer->data;
57	  } else {
58	    if (var_remap.count(buffer->data)) {
59	      new_var = var_remap[buffer->data];
60	    } else {
61	      new_var = Var(buffer->data->name_hint, new_type);
62	      var_remap.Set(buffer->data, new_var);
63	    }
64	  }
65	  Array<PrimExpr> layout_shape = layout->OutputShape();
66	  Array<PrimExpr> output_shape = layout_shape;
67	  if (IsSharedBuffer(buffer)) {
68	    int replicate_extent = 1;
69	    Array<PrimExpr> buffer_shape = buffer->shape;
70	    int buffer_extent = 1;
71	    int layout_extent = 1;
72	    for (size_t i = 0; i < buffer_shape.size(); i++) {
73	      auto shape = buffer_shape[i].as<IntImmNode>();
74	      buffer_extent *= shape->value;
75	    }
76	    for (size_t i = 0; i < layout_shape.size(); i++) {
77	      auto shape = layout_shape[i].as<IntImmNode>();
78	      ICHECK(shape) << "Layout output shape must be constant integer, but got: "
79	                    << layout_shape[i];
80	      layout_extent *= shape->value;
81	    }
82	    replicate_extent = buffer_extent / layout_extent;
83	    if (replicate_extent > 1) {
84	      output_shape.insert(output_shape.begin(), replicate_extent);
85	    }
86	  }
87	  return Buffer(new_var, buffer->dtype, output_shape, {}, buffer->elem_offset,
88	                buffer->name, buffer->data_alignment, buffer->offset_factor,
89	                buffer->buffer_type);
90	}
91	
92	// The function `makeBufferWithLayout` creates a new Buffer object based on the
93	// given buffer and layout. It handles remapping of buffer variables, adjusts
94	// the storage scope if needed (e.g., from "local.fragment" to "local"), and
95	// computes the output shape according to the layout. For shared memory buffers,
96	// it also handles replication if the buffer's extent is larger than the
97	// layout's extent.
98	class LayoutRemapRewriter : public arith::IRMutatorWithAnalyzer {
99	public:
100	  static Stmt Substitute(Stmt stmt, Map<Buffer, Layout> layout_remap) {
101	    arith::Analyzer analyzer;
102	    LayoutRemapRewriter substituter(&analyzer);
103	    substituter.layout_remap_ = std::move(layout_remap);
104	    return substituter.VisitStmt(stmt);
105	  }
106	
107	private:
108	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
109	
110	  Stmt VisitStmt_(const SBlockNode *op) final {
111	    auto block = Downcast<SBlock>(arith::IRMutatorWithAnalyzer::VisitStmt_(op));
112	    if (op->annotations.count(attr::kLayoutMap)) {
113	      block.CopyOnWrite()->annotations.Set(attr::kLayoutMap, layout_remap_);
114	    }
115	    return block;
116	  }
117	
118	  Map<Buffer, Layout> layout_remap_;
119	};
