121	/*!
122	 * \brief A class that rewrites buffer references in a statement based on a
123	 * given buffer remapping.
124	 *
125	 * This class is used to update buffer references in a statement after buffer
126	 * transformations have been applied. It specifically handles the remapping of
127	 * padding annotations.
128	 */
129	class RemapBufferRewriter : public arith::IRMutatorWithAnalyzer {
130	public:
131	  /*!
132	   * \brief Substitute buffer references in a statement based on a given buffer
133	   * remapping. \param stmt The statement to rewrite. \param buffer_remap A map
134	   * from old buffers to new buffers. \return The rewritten statement.
135	   */
136	  static Stmt Substitute(const Stmt &stmt, Map<Buffer, Buffer> buffer_remap) {
137	    arith::Analyzer analyzer;
138	    RemapBufferRewriter substituter(&analyzer);
139	    substituter.remap_ = std::move(buffer_remap);
140	    return substituter.VisitStmt(stmt);
141	  }
142	
143	private:
144	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
145	
146	  Stmt VisitStmt_(const SBlockNode *op) final {
147	    if (op->annotations.count(attr::kSafeValueMap)) {
148	      return RewritePaddingMap(op);
149	    }
150	    return IRMutatorWithAnalyzer::VisitStmt_(op);
151	  }
152	
153	  Stmt RewritePaddingMap(const SBlockNode *op) {
154	    auto safe_value_map = op->annotations.Get(attr::kSafeValueMap);
155	    if (!safe_value_map) {
156	      LOG(FATAL) << "Padding map annotation is missing";
157	    }
158	
159	    Map<Var, Var> var_remap = CreateVarRemap();
160	    Map<Var, PrimExpr> new_safe_value_map = RemapPaddingMap(
161	        Downcast<Map<Var, PrimExpr>>(safe_value_map.value()), var_remap);
162	
163	    auto block = Downcast<SBlock>(IRMutatorWithAnalyzer::VisitStmt_(op));
164	    auto block_ptr = block.CopyOnWrite();
165	    block_ptr->annotations.Set(attr::kSafeValueMap, new_safe_value_map);
166	    return block;
167	  }
168	
169	  Map<Var, Var> CreateVarRemap() const {
170	    Map<Var, Var> var_remap;
171	    for (const auto &[buffer, remapped] : remap_) {
172	      var_remap.Set(buffer->data, remapped->data);
173	    }
174	    return var_remap;
175	  }
176	
177	  Map<Var, PrimExpr> RemapPaddingMap(const Map<Var, PrimExpr> &safe_value_map,
178	                                     const Map<Var, Var> &var_remap) const {
179	    Map<Var, PrimExpr> new_safe_value_map;
180	    for (const auto &[var, padding] : safe_value_map) {
181	      if (var_remap.count(var)) {
182	        new_safe_value_map.Set(var_remap.at(var), padding);
183	      } else {
184	        new_safe_value_map.Set(var, padding);
185	      }
186	    }
187	    return new_safe_value_map;
188	  }
189	
190	  Map<Buffer, Buffer> remap_;
191	};
