193	/*! \brief Rewrite the synthetic CPU fallback thread variable to a constant.
194	 *
195	 * CPU `c` kernels use a degenerate fallback thread variable while fragment and
196	 * tile-op lowering still share thread-oriented helper code. After this pass has
197	 * consumed that helper variable, it should not remain in lowered CPU TIR.
198	 */
199	class CPUFallbackThreadVarCanonicalizer : public StmtExprMutator {
200	public:
201	  static Stmt Rewrite(Stmt stmt, Var fallback_thread_var) {
202	    CPUFallbackThreadVarCanonicalizer canonicalizer(
203	        std::move(fallback_thread_var));
204	    return canonicalizer(std::move(stmt));
205	  }
206	
207	private:
208	  explicit CPUFallbackThreadVarCanonicalizer(Var fallback_thread_var)
209	      : fallback_thread_var_(std::move(fallback_thread_var)) {}
210	
211	  PrimExpr VisitExpr_(const VarNode *op) final {
212	    if (fallback_thread_var_.defined() &&
213	        (op == fallback_thread_var_.get() ||
214	         op->name_hint == fallback_thread_var_->name_hint)) {
215	      return make_zero(op->dtype);
216	    }
217	    return StmtExprMutator::VisitExpr_(op);
218	  }
219	
220	  Var fallback_thread_var_;
221	};
