223	class LowerTileOpPass : arith::IRMutatorWithAnalyzer {
224	public:
225	  static PrimFunc Substitute(PrimFunc f) {
226	    arith::Analyzer analyzer;
227	    LowerTileOpPass substituter(&analyzer);
228	    // Trace the buffer map for tvm_access_ptr
229	    // Insert both handle var and data var as keys for lookup
230	    for (const auto &[param_var, buffer] : f->buffer_map) {
231	      substituter.buffer_map_.insert(
232	          {param_var, buffer}); // handle key (e.g., dQ_handle)
233	      substituter.buffer_map_.insert(
234	          {buffer->data, buffer}); // data key (e.g., dQ)
235	    }
236	    for (const auto &[_, buffer] : f->buffer_map) {
237	      substituter.buffer_data_to_buffer_.Set(buffer->data, buffer);
238	    }
239	    auto target = f->GetAttr<Target>(tvm::attr::kTarget);
240	    ICHECK(target.defined()) << "LowerTileOpPass: Require the target attribute";
241	    substituter.target_ = target.value();
242	    PrimFuncNode *fptr = f.CopyOnWrite();
243	    fptr->body = substituter.VisitStmt(f->body);
244	    fptr->body =
245	        RemapBufferRewriter::Substitute(fptr->body, substituter.buffer_remap_);
246	    fptr->body =
247	        LayoutRemapRewriter::Substitute(fptr->body, substituter.layout_remap_);
248	    // Record whether TMA was actually used as a PrimFunc attribute so that
249	    // later phases (OptimizeForTarget) can choose the right pass pipeline
250	    // without relying on pass-context side-channel mutation.
251	    f = WithAttr(std::move(f), kHasTMA, Bool(substituter.has_tma_));
252	    // Propagate per-buffer shared-memory alignment requirements collected
253	    // during lowering (swizzle-dependent TMA/MMA constraints) so that
254	    // MergeSharedMemoryAllocations can honor them when laying out the merged
255	    // dynamic shared memory buffer.
256	    if (!substituter.smem_alignment_map_.empty()) {
257	      f = WithAttr(std::move(f), kSmemAlignmentMap,
258	                   substituter.smem_alignment_map_);
259	    }
260	    fptr = f.CopyOnWrite();
261	
262	    // If any TMA copies allocated mbarriers, inject the barrier buffer
263	    // into the tilelang_root block with a barrier_init annotation.
264	    // Pipeline buffer versioning expands it for pipelining, and
265	    // LowerSharedBarrier will process it into ptx_init_barrier_thread_count.
266	    if (substituter.mbarrier_count_ > 0) {
267	      ICHECK(substituter.mbarrier_buffer_.defined())
268	          << "mbarrier_buffer_ must have been created by alloc_mbarrier "
269	             "callback";
270	      Buffer mbar_buf = substituter.mbarrier_buffer_.value();
271	      // Update buffer shape in-place to final count. We use const_cast
272	      // because CopyOnWrite would create a new BufferNode, breaking identity
273	      // with BufferLoad references already in the body. Pipeline buffer
274	      // versioning relies on buffer identity to remap accesses correctly.
275	      const_cast<BufferNode *>(mbar_buf.get())->shape = {
276	          IntImm(DataType::Int(32), substituter.mbarrier_count_)};
277	
278	      Array<PrimExpr> counts;
279	      counts.reserve(substituter.mbarrier_count_);
280	      for (auto c : substituter.mbarrier_arrive_counts_)
281	        counts.push_back(IntImm(DataType::Int(32), c));
282	
283	      // Walk the body to find the inner "tilelang_root" SBlockRealize
284	      // (inside the threadIdx.x scope) and inject the barrier buffer
285	      // + barrier_init annotation.
286	      struct RootBlockInjector : public StmtMutator {
287	        Buffer barrier_buf;
288	        Array<PrimExpr> arrive_counts;
289	        bool injected{false};
290	
291	        Stmt VisitStmt_(const SBlockRealizeNode *op) final {
292	          if (injected)
293	            return StmtMutator::VisitStmt_(op);
294	          if (op->block->name_hint == "root") {
295	            return StmtMutator::VisitStmt_(op);
296	          }
297	          injected = true;
298	          SBlock block = op->block;
299	          auto block_ptr = block.CopyOnWrite();
300	          block_ptr->alloc_buffers.push_back(barrier_buf);
301	          Map<Var, Array<PrimExpr>> barrier_init_map;
302	          if (block_ptr->annotations.count("barrier_init")) {
303	            barrier_init_map = Downcast<Map<Var, Array<PrimExpr>>>(
304	                block_ptr->annotations.at("barrier_init"));
305	          }
306	          barrier_init_map.Set(barrier_buf->data, arrive_counts);
307	          block_ptr->annotations.Set("barrier_init", barrier_init_map);
308	          auto realize = GetRef<SBlockRealize>(op);
309	          auto realize_ptr = realize.CopyOnWrite();
310	          realize_ptr->block = block;
311	          return realize;
312	        }
313	      };
314	
315	      RootBlockInjector injector;
316	      injector.barrier_buf = mbar_buf;
317	      injector.arrive_counts = counts;
318	      fptr->body = injector(fptr->body);
319	      ICHECK(injector.injected)
320	          << "Failed to find root SBlockRealize for barrier injection";
321	    }
322	
323	    if (TargetIsCPU(substituter.target_)) {
324	      // TODO(#2226): Remove the underlying CPU fallback-thread placeholder
325	      // shared by LayoutInference/LowerTileOp. Until then, canonicalize the
326	      // synthetic fallback after fragment/tile lowering has consumed it.
327	      fptr->body = CPUFallbackThreadVarCanonicalizer::Rewrite(
328	          std::move(fptr->body), substituter.thread_var_->var);
329	    }
330	
331	    return f;
332	  }
333	
334	private:
335	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
336	
337	  Stmt VisitStmt_(const SBlockNode *op) final {
338	    // Record the mapping from buffer data var to buffer for later lookup
339	    for (auto buffer : op->alloc_buffers) {
340	      buffer_map_.insert({buffer->data, buffer});
341	    }
342	    for (auto match_buffer : op->match_buffers) {
343	      buffer_map_.insert({match_buffer->buffer->data, match_buffer->buffer});
344	    }
345	    for (auto buffer : op->alloc_buffers) {
346	      buffer_data_to_buffer_.Set(buffer->data, buffer);
347	    }
348	    Map<Var, Layout> vmap;
349	    if (op->annotations.count(attr::kLayoutMap)) {
350	      auto layout_map = op->annotations.at(attr::kLayoutMap)
351	                            .as<Map<Buffer, Layout>>()
352	                            .value();
353	      for (auto [buffer, layout] : layout_map) {
354	        buffer_remap_.Set(buffer,
355	                          makeBufferWithLayout(buffer, layout, var_remap_));
356	        layout_map_.Set(buffer, layout);
357	      }
358	    }
359	    // Extract cluster_size from cluster_dims annotation
360	    if (op->annotations.count("cluster_dims")) {
361	      if (auto arr =
362	              op->annotations.Get("cluster_dims")->try_cast<Array<Integer>>()) {
363	        int sz = 1;
364	        for (auto d : arr.value())
365	          sz *= static_cast<int>(d->value);
366	        cluster_size_ = sz;
367	      }
368	    }
369	    // Begin a new workspace collection frame for this block scope
370	    workspace_stack_.emplace_back();
371	
372	    auto block = Downcast<SBlock>(arith::IRMutatorWithAnalyzer::VisitStmt_(op));
373	    auto block_ptr = block.CopyOnWrite();
374	    for (size_t i = 0; i < block->alloc_buffers.size(); i++) {
375	      auto buffer = block->alloc_buffers[i];
376	      if (buffer_remap_.count(buffer)) {
377	        block_ptr->alloc_buffers.Set(i, buffer_remap_[buffer]);
378	      } else if (IsFragmentBuffer(buffer)) {
379	        const auto *ptr_type =
380	            TVM_TYPE_AS(buffer->data->type_annotation, PointerTypeNode);
381	        Type new_type = PointerType(ptr_type->element_type, "local");
382	        Var new_var;
383	        if (var_remap_.count(buffer->data)) {
384	          new_var = var_remap_[buffer->data];
385	        } else {
386	          new_var = Var(buffer->data->name_hint, new_type);
387	          var_remap_.Set(buffer->data, new_var);
388	        }
389	        Buffer new_buf(new_var, buffer->dtype, buffer->shape, buffer->strides,
390	                       buffer->elem_offset, buffer->name,
391	                       buffer->data_alignment, buffer->offset_factor,
392	                       buffer->buffer_type);
393	        buffer_remap_.Set(buffer, new_buf);
394	        block_ptr->alloc_buffers.Set(i, new_buf);
395	      }
396	    }
397	    // Attach any workspaces requested within this block to its alloc_buffers
398	    if (!workspace_stack_.empty()) {
399	      for (const auto &buffer : workspace_stack_.back()) {
400	        block_ptr->alloc_buffers.push_back(buffer);
401	      }
402	      workspace_stack_.pop_back();
403	    }
404	
405	    // Apply arrive-count overrides before LowerSharedBarrier consumes them.
406	    if (!barrier_arrive_updates_.empty() &&
407	        block->annotations.count("barrier_init")) {
408	      auto barrier_init_map = Downcast<Map<Var, Array<PrimExpr>>>(
409	          block->annotations.Get("barrier_init").value());
410	      bool updated = false;
411	      for (auto it = barrier_arrive_updates_.begin();
412	           it != barrier_arrive_updates_.end();) {
413	        if (barrier_init_map.count(it->first)) {
414	          auto old_counts = barrier_init_map.at(it->first);
415	          Array<PrimExpr> new_counts;
416	          for (size_t i = 0; i < old_counts.size(); i++) {
417	            new_counts.push_back(it->second);
418	          }
419	          barrier_init_map.Set(it->first, new_counts);
420	          updated = true;
421	          it = barrier_arrive_updates_.erase(it);
422	        } else {
423	          ++it;
424	        }
425	      }
426	      if (updated) {
427	        block_ptr->annotations.Set("barrier_init", barrier_init_map);
428	      }
429	    }
430	
431	    return block;
432	  }
433	
434	  int CheckAndGetBufferRowSize(const Buffer &buffer) {
435	    ICHECK(buffer->shape.size() >= 2)
436	        << "The dimension of Buffer \"" << buffer->name << "\" with shape "
437	        << buffer->shape << " should be at least 2";
438	
439	    auto dim = buffer->shape.size();
440	    auto buffer_row_size = buffer->shape[dim - 1].as<IntImmNode>()->value;
441	    return buffer_row_size;
442	  }
