444	  struct AccessPtrResult {
445	    PrimExpr expr;
446	    bool rewritten{false};
447	  };
448	
449	  AccessPtrResult
450	  HandleAccessPtrAndOffset(const PrimExpr &access_ptr,
451	                           const Optional<PrimExpr> &offset = std::nullopt,
452	                           DataType dtype = DataType::Int(32)) {
453	    AccessPtrResult result{access_ptr, false};
454	    // The 2th arg of T.tvm_access_ptr call is offset, we set it to 0 and
455	    // accumulate it to smem_offset
456	    ICHECK(access_ptr->IsInstance<CallNode>())
457	        << "Invalid access ptr for permuted layout: " << access_ptr;
458	    auto access_ptr_call = Downcast<Call>(access_ptr);
459	    if (access_ptr_call->op.same_as(builtin::tvm_access_ptr())) {
460	      // tvm_access_ptr format: (dtype, data, offset, extent, rw_mask)
