750	  Optional<PrimExpr> ResolveBufferLoad(const PrimExpr &expr) const {
751	    if (expr->IsInstance<BufferLoadNode>()) {
752	      return expr;
753	    }
754	    if (const auto *var_node = expr.as<VarNode>()) {
755	      Var var = GetRef<Var>(var_node);
756	      auto it = bind_var_to_expr_.find(var);
757	      if (it != bind_var_to_expr_.end()) {
758	        return it->second;
759	      }
760	    }
761	    return Optional<PrimExpr>();
762	  }
763	
764	  Optional<Buffer> FindRemapBuffer(const Buffer &buffer) const {
765	    if (buffer_remap_.count(buffer)) {
766	      return buffer;
767	    }
768	    auto it = buffer_map_.find(buffer->data);
769	    if (it != buffer_map_.end() && buffer_remap_.count(it->second)) {
770	      return it->second;
771	    }
772	    for (const auto &kv : buffer_remap_) {
773	      if (kv.first->data.same_as(buffer->data)) {
774	        return kv.first;
775	      }
776	      if (kv.first->name == buffer->name) {
777	        return kv.first;
778	      }
779	    }
780	    return Optional<Buffer>();
781	  }
782	
783	  Optional<Layout> FindLayout(const Buffer &buffer) const {
784	    if (layout_map_.count(buffer)) {
785	      return layout_map_[buffer];
786	    }
787	    auto it = buffer_map_.find(buffer->data);
788	    if (it != buffer_map_.end() && layout_map_.count(it->second)) {
789	      return layout_map_[it->second];
790	    }
791	    for (const auto &kv : layout_map_) {
792	      if (kv.first->data.same_as(buffer->data)) {
793	        return kv.second;
794	      }
795	      if (kv.first->name == buffer->name) {
796	        return kv.second;
797	      }
798	    }
799	    return Optional<Layout>();
800	  }
