961	          auto call_node = call.CopyOnWrite();
962	          call_node->args.Set(
963	              2, Call(access_ptr_call->dtype, access_ptr_call->op, {load_expr},
964	                      access_ptr_call->annotations, access_ptr_call->span));
965	          access_ptr_call = Downcast<Call>(call->args[2]);
966	          access_ptr = call->args[2];
967	        }
968	        auto new_access_ptr =
969	            HandleAccessPtrAndOffset(access_ptr, std::nullopt, call->dtype);
970	        if (new_access_ptr.rewritten) {
971	          auto new_call = call.CopyOnWrite();
972	          new_call->args.Set(2, new_access_ptr.expr);
973	        }
974	      } else if (access_ptr_call->op.same_as(tl::access_ptr())) {
975	        auto new_access_ptr =
976	            HandleAccessPtrAndOffset(access_ptr, std::nullopt, call->dtype);
977	        if (new_access_ptr.rewritten) {
978	          auto new_call = call.CopyOnWrite();
979	          new_call->args.Set(2, new_access_ptr.expr);
980	        }
981	      } else {
982	        LOG(FATAL) << "Invalid access ptr for permuted layout: " << access_ptr;
983	      }
984	      return call;
985	    }
986	
987	    // Handle mma_store
988	    if (op->op.same_as(builtin::mma_store())) {
989	      is_ptx_ = true;
990	      auto call = Downcast<Call>(IRMutatorWithAnalyzer::VisitExpr_(op));
991	      is_ptx_ = false;
992	      // because we will directly store result to Buffer instead of calling
993	      // mma_store now
994	      auto access_ptr = call->args[2];
995	      auto new_access_ptr =
996	          HandleAccessPtrAndOffset(access_ptr, std::nullopt, call->dtype);
997	      if (new_access_ptr.rewritten) {
998	        auto new_call = call.CopyOnWrite();
999	        new_call->args.Set(2, new_access_ptr.expr);
1000	      }
1001	      return call;
1002	    }
1003	
1004	    // Handle standalone tvm_access_ptr calls with layout transformation
1005	    if (op->op.same_as(builtin::tvm_access_ptr())) {
1006	      auto call = Downcast<Call>(IRMutatorWithAnalyzer::VisitExpr_(op));
1007	      auto new_access_ptr =
1008	          HandleAccessPtrAndOffset(call, std::nullopt, call->dtype);
1009	      if (new_access_ptr.rewritten) {
1010	        return new_access_ptr.expr;
1011	      }
1012	      return call;
1013	    }
1014	
1015	    // Default: visit normally
1016	    auto call = Downcast<Call>(IRMutatorWithAnalyzer::VisitExpr_(op));
1017	    return call;
1018	  }
1019	
1020	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
1021	    auto load = Downcast<BufferLoad>(IRMutatorWithAnalyzer::VisitExpr_(op));
1022	    if (is_ptx_) {
1023	      return load;
1024	    }
1025	    auto buffer = load->buffer;
1026	    if (buffer_remap_.count(buffer)) {
1027	      auto new_indices = layout_map_[buffer]->Forward(load->indices);
1028	      auto new_buffer = buffer_remap_[load->buffer];
1029	      layout_remap_.Set(new_buffer, layout_map_[load->buffer]);
1030	      return BufferLoad(new_buffer, new_indices);
1031	    } else if (var_remap_.count(buffer->data)) {
1032	      auto new_buffer = Buffer(
1033	          var_remap_[buffer->data], buffer->dtype, buffer->shape,
1034	          buffer->strides, buffer->elem_offset, buffer->name,
1035	          buffer->data_alignment, buffer->offset_factor, buffer->buffer_type);
1036	      return BufferLoad(new_buffer, load->indices);
1037	    }
1038	    return load;
1039	  }
1040	
1041	  Stmt VisitStmt_(const BufferStoreNode *op) final {
1042	    auto store = Downcast<BufferStore>(IRMutatorWithAnalyzer::VisitStmt_(op));
1043	    auto buffer = store->buffer;
1044	    if (buffer_remap_.count(buffer)) {
1045	      auto new_indices = layout_map_[buffer]->Forward(store->indices);
1046	      auto new_buffer = buffer_remap_[store->buffer];
1047	      layout_remap_.Set(new_buffer, layout_map_[store->buffer]);
1048	      return BufferStore(new_buffer, store->value, new_indices);
1049	    } else if (var_remap_.count(buffer->data)) {
1050	      auto new_buffer = Buffer(
1051	          var_remap_[buffer->data], buffer->dtype, buffer->shape,
1052	          buffer->strides, buffer->elem_offset, buffer->name,
1053	          buffer->data_alignment, buffer->offset_factor, buffer->buffer_type);
1054	      return BufferStore(new_buffer, store->value, store->indices);
1055	    }
1056	    return store;
1057	  }
1058	
1059	  PrimExpr VisitExpr_(const VarNode *op) final {
1060	    auto var = Downcast<Var>(IRMutatorWithAnalyzer::VisitExpr_(op));
1061	    if (buffer_data_to_buffer_.count(var)) {
1062	      auto buffer = buffer_data_to_buffer_[var];
1063	      if (buffer_remap_.count(buffer))
1064	        return buffer_remap_[buffer]->data;
1065	    }
1066	    return var;
1067	  }
1068	
1069	  Stmt VisitStmt_(const BindNode *op) final {
1070	    PrimExpr value = this->VisitExpr(op->value);
1071	    bool recorded = false;
1072	    if (value->IsInstance<BufferLoadNode>()) {
1073	      bind_var_to_expr_[op->var] = value;
1074	      recorded = true;
1075	    }
1076	    if (SideEffect(value) <= CallEffectKind::kPure) {
1077	      analyzer_->Bind(op->var, value);
1078	    }
1079	    if (value.same_as(op->value)) {
1080	      return GetRef<Stmt>(op);
1081	    } else {
1082	      auto n = this->CopyOnWrite(op);
1083	      n->value = value;
1084	      return Stmt(n);
1085	    }
1086	  }
