1088	  /**
1089	   * @brief Handle an Evaluate node, lowering a detected tile operator to TIR.
1090	   *
1091	   * This visit implementation detects whether the Evaluate node represents a
1092	   * tile operator invocation (via ParseOperator). If no tile operator is found
1093	   * or the call targets a global function, the node is delegated to the base
1094	   * visitor.
1095	   *
1096	   * When a tile operator is present, the method:
1097	   * - Builds a workspace-allocation callback that creates a dynamic shared
1098	   * buffer named "workspace" (storage scope "shared.dyn") and returns its write
1099	   *   access pointer.
1100	   * - Determines thread bounds for lowering from the analyzer's constant-int
1101	   *   information for thread_var_; if unavailable, a default range [0,1) is
1102	   * used.
1103	   * - Invokes tile_op->Lower(...) with LowerArgs containing target, thread
1104	   *   bounds, thread variable, the workspace callback, layout and buffer remap
1105	   *   maps, and the list of GEMM-involved buffer vars; the analyzer is passed
1106	   *   through for use during lowering.
1107	   *
1108	   * The lowered statement returned by the operator is then visited by the base
1109	   * IRMutatorWithAnalyzer and that result is returned.
1110	   *
1111	   * @return Stmt The (possibly transformed) statement after lowering or base
1112	   * visitor processing.
1113	   */
1114	  Stmt VisitStmt_(const AllocBufferNode *op) final {
1115	    auto buffer = op->buffer;
1116	    if (buffer_remap_.count(buffer)) {
1117	      auto node = Downcast<AllocBuffer>(IRMutatorWithAnalyzer::VisitStmt_(op));
1118	      node.CopyOnWrite()->buffer = buffer_remap_[buffer];
1119	      return std::move(node);
1120	    }
1121	    if (IsFragmentBuffer(buffer)) {
1122	      const auto *ptr_type =
1123	          TVM_TYPE_AS(buffer->data->type_annotation, PointerTypeNode);
1124	      Type new_type = PointerType(ptr_type->element_type, "local");
1125	      Var new_var;
1126	      if (var_remap_.count(buffer->data)) {
1127	        new_var = var_remap_[buffer->data];
1128	      } else {
1129	        new_var = Var(buffer->data->name_hint, new_type);
1130	        var_remap_.Set(buffer->data, new_var);
1131	      }
1132	      Buffer new_buf(new_var, buffer->dtype, buffer->shape, buffer->strides,
1133	                     buffer->elem_offset, buffer->name, buffer->data_alignment,
1134	                     buffer->offset_factor, buffer->buffer_type);
1135	      buffer_remap_.Set(buffer, new_buf);
1136	      auto node = Downcast<AllocBuffer>(IRMutatorWithAnalyzer::VisitStmt_(op));
1137	      node.CopyOnWrite()->buffer = new_buf;
1138	      return std::move(node);
1139	    }
1140	    return IRMutatorWithAnalyzer::VisitStmt_(op);
1141	  }
1142	
1143	  Stmt VisitStmt_(const EvaluateNode *op) final {
1144	    const CallNode *call = op->value.as<CallNode>();
1145	    // Do not analysis the call node to the global function.
1146	    if (call && call->op.as<GlobalVarNode>())
1147	      return Downcast<Evaluate>(IRMutatorWithAnalyzer::VisitStmt_(op));
1148	
1149	    auto tile_op = ParseOperator(GetRef<Stmt>(op));
1150	    if (!tile_op.defined())
1151	      return IRMutatorWithAnalyzer::VisitStmt_(op);
1152	
1153	    Range thread_bounds = CurrentThreadBounds();
1154	
1155	    // Convert bind_var_to_expr_ to Map<Var, PrimExpr> for LowerArgs
1156	    Map<Var, PrimExpr> bind_var_to_expr;
1157	    for (const auto &[var, expr] : bind_var_to_expr_) {
1158	      bind_var_to_expr.Set(var, expr);
1159	    }
1160	
1161	    AddWorkspaceCallback add_workspace_callback = [this](int num_elem,
1162	                                                         DataType dtype) {
1163	      auto workspace =
1164	          decl_buffer({PrimExpr(num_elem)}, dtype, "workspace", "shared.dyn");
1165	      // Record workspace under the innermost block scope so its lifetime
1166	      // covers the statements that requested it and does not sink into
1167	      // subsequently created inner blocks (e.g., GEMM macro blocks).
1168	      if (!workspace_stack_.empty()) {
1169	        workspace_stack_.back().push_back(workspace);
1170	      } else {
1171	        // Fallback: create a temporary frame (should be rare)
1172	        workspace_stack_.emplace_back(Array<Buffer>{workspace});
1173	      }
1174	      return workspace.access_ptr(2); // write
1175	    };
1176	
1177	    AllocMBarrierCallback mbarrier_callback =
1178	        [this](int arrive_count, std::optional<std::string> name) -> int {
1179	      if (!mbarrier_buffer_.defined()) {
1180	        mbarrier_buffer_ =
1181	            CreateMBarrierBuffer(name.value_or(injected_mbarrier_name_), 1);
1182	      }
1183	      int id = mbarrier_count_++;
1184	      mbarrier_arrive_counts_.push_back(arrive_count);
1185	      return id;
1186	    };
1187	
1188	    UpdateBarrierArriveCallback barrier_arrive_callback = [this](Var data_var,
1189	                                                                 PrimExpr n) {
1190	      barrier_arrive_updates_[data_var] = n;
1191	    };
1192	
1193	    RequireSmemAlignmentCallback require_smem_alignment_callback =
1194	        [this](Var data_var, int alignment) {
1195	          String key = data_var->name_hint;
1196	          auto it = smem_alignment_map_.find(key);
1197	          int64_t prev =
1198	              it != smem_alignment_map_.end() ? (*it).second->value : 0;
1199	          if (alignment > prev) {
1200	            smem_alignment_map_.Set(key, IntImm(DataType::Int(32), alignment));
1201	          }
1202	        };
1203	
1204	    LowerArgs lower_args;
1205	    lower_args.target = target_;
1206	    lower_args.thread_bounds = thread_bounds;
1207	    lower_args.thread_var = thread_var_->var;
1208	    lower_args.layout_map = layout_map_;
1209	    lower_args.buffer_remap = buffer_remap_;
1210	    lower_args.bind_var_to_expr = bind_var_to_expr;
1211	    lower_args.mbar_phase_expr = loop_mbar_phase_stack_.empty()
1212	                                     ? PrimExpr(IntImm(DataType::Int(32), 0))
1213	                                     : loop_mbar_phase_stack_.back();
1214	    lower_args.mbarrier_buffer = &mbarrier_buffer_;
1215	    lower_args.cluster_size = cluster_size_;
1216	    lower_args.add_workspace = add_workspace_callback;
1217	    lower_args.alloc_mbarrier = mbarrier_callback;
1218	    lower_args.update_barrier_arrive = barrier_arrive_callback;
1219	    lower_args.require_smem_alignment = require_smem_alignment_callback;
1220	
1221	    auto lowered = tile_op->Lower(lower_args, analyzer_);
1222	
1223	    return IRMutatorWithAnalyzer::VisitStmt(lowered);
1224	  }
1225	
1226	  Stmt VisitStmt_(const AttrStmtNode *op) final {
1227	    if (op->attr_key == tirx::attr::thread_extent) {
1228	      IterVar iv = Downcast<IterVar>(op->node);
1229	      ICHECK_NE(iv->thread_tag.length(), 0U);
1230	      if (iv->thread_tag == "threadIdx.x") {
1231	        thread_var_ = iv;
1232	        ICHECK(iv->dom->extent.as<IntImmNode>());
1233	        thread_block_size_ = iv->dom->extent.as<IntImmNode>()->value;
1234	      }
1235	    }
1236	    return arith::IRMutatorWithAnalyzer::VisitStmt_(op);
1237	  }
1238	
1239	  /**
1240	   * @brief Handle a Parallel For node, lowering it based on the layout
1241	   * annotation.
1242	   *
1243	   * This method checks if the For node has a parallel_loop_layout annotation.
1244	   * If the For node is a parallel loop (ForKind::kParallel):
1245	   * - It must have the parallel_loop_layout annotation, otherwise an error is
1246	   *   raised.
1247	   * - The loop is partitioned and vectorized based on the annotated layout.
1248	   * - If a predicate annotation exists, the loop is wrapped with an IfThenElse.
1249	   *
1250	   * Special handling for reducers and local buffers:
1251	   * - If the loop stores into local buffers, thread partitioning is skipped.
1252	   * - If the loop only manipulates local buffers, thread partitioning is
1253	   * skipped.
1254	   * - If reducers are present, vectorization is skipped.
1255	   * - Vectorization is only applied if non-local buffers or vectorizable casts
1256	   *   are present.
1257	   *
1258	   * @return Stmt The lowered statement.
1259	   */
1260	  Stmt VisitStmt_(const ForNode *op) final {
1261	    bool pushed_loop_mbar_phase = false;
1262	    if (op->kind == ForKind::kSerial) {
1263	      int num_stages = 1;
1264	      if (auto ns_anno = op->annotations.Get("num_stages")) {
1265	        if (const auto *ns_int = ns_anno.value().as<IntImmNode>()) {
1266	          if (ns_int->value > 1) {
1267	            num_stages = static_cast<int>(ns_int->value);
1268	          }
1269	        }
1270	      }
1271	      PrimExpr phase_expr;
1272	      DataType loop_dtype = op->loop_var.dtype();
1273	      PrimExpr two = make_const(loop_dtype, 2);
1274	      if (num_stages > 1) {
1275	        PrimExpr num_stages_expr = make_const(loop_dtype, num_stages);
1276	        phase_expr = FloorMod(FloorDiv(op->loop_var, num_stages_expr), two);
1277	      } else {
1278	        phase_expr = FloorMod(op->loop_var, two);
1279	      }
1280	      loop_mbar_phase_stack_.push_back(analyzer_->Simplify(phase_expr));
1281	      pushed_loop_mbar_phase = true;
1282	    }
1283	
1284	    // Extract reducer info from annotations
1285	    Map<Var, ReducerInfo> reducer_info;
1286	    if (op->annotations.count(attr::kReducerInfo)) {
1287	      reducer_info = op->annotations.Get(attr::kReducerInfo)
1288	                         ->as<Map<Var, ReducerInfo>>()
1289	                         .value();
1290	    }
1291	
1292	    // First visit the body.
1293	    For for_node = Downcast<For>(arith::IRMutatorWithAnalyzer::VisitStmt_(op));
1294	    if (pushed_loop_mbar_phase) {
1295	      loop_mbar_phase_stack_.pop_back();
1296	    }
1297	
1298	    // Only process parallel loops
1299	    if (op->kind != ForKind::kParallel) {
1300	      return for_node;
1301	    }
1302	
1303	    // For nested parallel loops, the annotation is placed on the outermost
1304	    // loop. Inner parallel loops without annotation should be skipped here –
1305	    // they will be processed as part of the outer loop's partitioning.
1306	    // Rationale: inner loops cannot govern their outer loops; the outermost
1307	    // loop is the correct place to carry layout so we can rewrite the whole
1308	    // nested region in one place.
1309	    if (!op->annotations.count(attr::kParallelLoopLayout)) {
1310	      return for_node;
1311	    }
1312	
1313	    auto loop_layout = Downcast<Fragment>(
1314	        op->annotations.Get(attr::kParallelLoopLayout).value());
1315	    // Get predicate if it exists
1316	    Optional<PrimExpr> predicate;
1317	    if (op->annotations.count(attr::kParallelLoopPredicate)) {
1318	      predicate = Downcast<PrimExpr>(
1319	          op->annotations.Get(attr::kParallelLoopPredicate).value());
1320	    }
1321	    bool require_padding_guard = false;
1322	    if (auto padding_guard_anno =
1323	            op->annotations.Get(attr::kParallelLoopRequiresPaddingGuard)) {
1324	      if (auto padding_guard_bool =
1325	              padding_guard_anno.value().try_cast<Bool>()) {
1326	        require_padding_guard = padding_guard_bool.value()->value;
1327	      } else if (auto padding_guard_int =
1328	                     padding_guard_anno.value().as<IntImmNode>()) {
1329	        require_padding_guard = padding_guard_int->value != 0;
1330	      } else {
1331	        LOG(WARNING) << "Loop annotation `"
1332	                     << attr::kParallelLoopRequiresPaddingGuard
1333	                     << "` expects Bool value (True/False), but got "
1334	                     << padding_guard_anno.value().GetTypeKey()
1335	                     << ". Ignore override.";
1336	      }
1337	    }
1338	    bool parallel_prefer_async = false;
1339	    if (auto prefer_async_anno = op->annotations.Get(attr::kLoopPreferAsync)) {
1340	      if (auto prefer_async_bool = prefer_async_anno.value().try_cast<Bool>()) {
1341	        parallel_prefer_async = prefer_async_bool.value()->value;
1342	      } else {
1343	        LOG(WARNING) << "Loop annotation `" << attr::kLoopPreferAsync
1344	                     << "` expects Bool value (True/False), but got "
1345	                     << prefer_async_anno.value().GetTypeKey()
1346	                     << ". Ignore override.";
1347	      }
1348	    }
1349	    bool parallel_async_without_async_commit_wait = false;
1350	    if (auto no_commit_wait_anno =
1351	            op->annotations.Get(attr::kParallelAsyncWithoutAsyncCommitWait)) {
1352	      if (auto no_commit_wait_bool =
1353	              no_commit_wait_anno.value().try_cast<Bool>()) {
1354	        parallel_async_without_async_commit_wait =
1355	            no_commit_wait_bool.value()->value;
1356	      } else {
1357	        LOG(WARNING) << "Loop annotation `"
1358	                     << attr::kParallelAsyncWithoutAsyncCommitWait
1359	                     << "` expects Bool value (True/False), but got "
1360	                     << no_commit_wait_anno.value().GetTypeKey()
1361	                     << ". Ignore override.";
1362	      }
1363	    }
1364	
1365	    auto root = GetRef<For>(op);
1366	
1367	    // Check if the loop writes to any non-local buffer or touches a fragment.
1368	    // Thread partitioning is unnecessary when all stores target local buffers
1369	    // and there are no fragment accesses.
1370	    // For example:
1371	    //   for i in T.Parallel(1024):
1372	    //     A_local[i] = A_global[i]
1373	    // Here, A_local is a register-local buffer held independently by each
1374	    // thread, so explicit thread binding is not required.
1375	
1376	    // NOTE: For cases when stores to both local and non-local buffers exist
1377	    // (mixed case), we still conservatively assume that thread partitioning is
1378	    // needed. In such case, the programmer should carefully consider the
1379	    // access patterns of the mixed accesses to ensure correctness.
1380	
1381	    // Element-level intrinsics (e.g. atomic_add) pass non-local buffer
1382	    // pointers via tvm_access_ptr / tl::access_ptr inside CallNodes.
1383	    bool has_non_local_store = false;
1384	    bool has_fragment_access = false;
1385	    PostOrderVisit(root, [&](const ObjectRef &obj) {
1386	      if (const auto *load = obj.as<BufferLoadNode>()) {
1387	        if (IsFragmentBuffer(load->buffer)) {
1388	          has_fragment_access = true;
1389	        }
1390	      } else if (const auto *store = obj.as<BufferStoreNode>()) {
1391	        if (IsFragmentBuffer(store->buffer)) {
1392	          has_fragment_access = true;
1393	        }
1394	        if (!IsLocalBuffer(store->buffer)) {
1395	          has_non_local_store = true;
1396	        }
1397	      } else if (const auto *call = obj.as<CallNode>()) {
1398	        if (call->op.same_as(builtin::tvm_access_ptr())) {
1399	          // tvm_access_ptr format: (dtype, data, offset, extent, rw_mask)
1400	          auto buffer_var = call->args[1].as<VarNode>();
1401	          if (buffer_var) {
1402	            Var var = GetRef<Var>(buffer_var);
1403	            auto it = buffer_map_.find(var);
1404	            if (it != buffer_map_.end()) {
1405	              if (IsFragmentBuffer(it->second)) {
1406	                has_fragment_access = true;
1407	              }
1408	              if (!IsLocalBuffer(it->second)) {
1409	                has_non_local_store = true;
1410	              }
1411	            }
1412	          }
1413	        } else if (call->op.same_as(tl::access_ptr())) {
1414	          // tl::access_ptr format: (BufferLoad, extent, rw_mask)
1415	          if (const auto *load = call->args[0].as<BufferLoadNode>()) {
1416	            if (IsFragmentBuffer(load->buffer)) {
1417	              has_fragment_access = true;
1418	            }
1419	            if (!IsLocalBuffer(load->buffer)) {
1420	              has_non_local_store = true;
1421	            }
1422	          }
1423	        } else if (call->op.same_as(builtin::address_of())) {
1424	          // call_extern may pass address_of(non-local-buffer) pointers, and
1425	          // PostOrderVisit reaches the address_of call directly.
1426	          if (const auto *load = call->args[0].as<BufferLoadNode>()) {
1427	            if (IsFragmentBuffer(load->buffer)) {
1428	              has_fragment_access = true;
1429	            }
1430	            if (!IsLocalBuffer(load->buffer)) {
1431	              has_non_local_store = true;
1432	            }
1433	          }
1434	        }
1435	      }
1436	    });
1437	
1438	    // Determine if this loop requires thread partitioning. Fragment accesses
1439	    // must be partitioned together with their layout rewrite: once a logical
1440	    // fragment index is lowered to a physical per-thread slot, the logical loop
1441	    // iteration has to be owned by the corresponding thread.
1442	    bool parallel_loop = has_non_local_store || has_fragment_access;
1443	
1444	    // Check if there are non-local buffer accesses (for vectorization decision)
1445	    bool has_non_local = false;
1446	    PostOrderVisit(for_node->body, [&](const ObjectRef &obj) {
1447	      if (const auto *load = obj.as<BufferLoadNode>()) {
1448	        if (!IsLocalBuffer(load->buffer, /*allow_var*/ true) &&
1449	            !IsFragmentBuffer(load->buffer)) {
1450	          has_non_local = true;
1451	        }
1452	      } else if (const auto *store = obj.as<BufferStoreNode>()) {
1453	        if (!IsLocalBuffer(store->buffer, /*allow_var*/ true) &&
1454	            !IsFragmentBuffer(store->buffer)) {
1455	          has_non_local = true;
1456	        }
1457	      }
1458	    });
1459	
1460	    // Check if reducers are present in the loop body
1461	    // Workaround: if reducer is presented, don't vectorize loop
1462	    // Best solution should be isolate reduction axis out of vectorization
1463	    //
1464	    // Note: reducer_info stores original buffer data vars, but after visiting
1465	    // the body, buffers may have been remapped via var_remap_. We need to find
1466	    // the original var to check against reducer_info.
1467	    bool has_reducer = false;
1468	    PostOrderVisit(for_node->body, [&](const ObjectRef &obj) {
1469	      if (!has_reducer) {
1470	        if (const auto *store = obj.as<BufferStoreNode>()) {
1471	          Var data_var = store->buffer->data;
1472	          // Find the original var if it was remapped
1473	          // var_remap_ maps old_var -> new_var, so we need reverse lookup
1474	          Var original_var = data_var;
1475	          for (const auto &[old_var, new_var] : var_remap_) {
1476	            if (new_var.same_as(data_var)) {
1477	              original_var = old_var;
1478	              break;
1479	            }
1480	          }
1481	          has_reducer = reducer_info.count(original_var) != 0;
1482	        }
1483	      }
1484	    });
1485	
1486	    // Check if vectorizable cast operations exist
1487	    bool has_cast_operations = false;
1488	    PostOrderVisit(for_node->body, [&](const ObjectRef &obj) {
1489	      if (const auto *cast = obj.as<CastNode>()) {
1490	        DataType from_ty = cast->value.dtype();
1491	        DataType target_ty = cast->dtype;
1492	        if (IsCudaVectorizableCast(from_ty, target_ty) &&
1493	            TargetIsCuda(Target::Current())) {
1494	          has_cast_operations = true;
1495	        }
1496	        if (IsMacaVectorizableCast(from_ty, target_ty) &&
1497	            TargetIsMaca(Target::Current())) {
1498	          has_cast_operations = true;
1499	        }
1500	      }
1501	    });
1502	
1503	    // Decide whether to vectorize:
1504	    // - Only if there are non-local buffers or vectorizable casts
1505	    // - AND no reducers are present
1506	    bool should_vectorize =
1507	        (has_non_local || has_cast_operations) && !has_reducer;
1508	    // Lower the parallel loop using the common function
1509	    Stmt lowered = LowerParallelLoop(
1510	        for_node, loop_layout, thread_var_->var, analyzer_, layout_map_,
1511	        predicate, parallel_loop, should_vectorize, require_padding_guard);
1512	
1513	    // Only parallel-loop lowering needs PTX cp.async injection. Thread-level
1514	    // lowering does not require converting eligible global->shared copies to
1515	    // `tir.ptx_cp_async`.
1516	    if (TargetCudaHasAsyncCopy(target_)) {
1517	      tvm::transform::PassContext ctx = tvm::transform::PassContext::Current();
1518	      bool auto_async_copy_enabled =
1519	          ctx->GetConfig<Bool>(kEnableAsyncCopy, Bool(true)).value();
1520	      bool should_inject_async_copy =
1521	          parallel_prefer_async ||
1522	          (auto_async_copy_enabled && parallel_async_without_async_commit_wait);
1523	      if (should_inject_async_copy) {
1524	        auto inject_result = InjectPTXAsyncCopy(
1525	            lowered, parallel_async_without_async_commit_wait);
1526	        lowered = inject_result.stmt;
1527	      }
1528	    }
1529	    return lowered;
1530	  }
1531	
1532	  Range CurrentThreadBounds() const {
1533	    return ComputeThreadBounds(thread_var_, *analyzer_);
1534	  }
1535	
1536	  Target target_;
1537	  Map<Var, Buffer> buffer_data_to_buffer_;
1538	  Map<Buffer, Layout> layout_map_;
1539	  Map<Buffer, Layout> layout_remap_;
1540	  Map<Buffer, Buffer> buffer_remap_;
1541	  // This is a workaround for cpu backend,
1542	  // we need to define a thread_var for the serial loop.
1543	  IterVar thread_var_ = IterVar(Range::FromMinExtent(0, 1), Var("v_thread"),
1544	                                IterVarType::kDataPar);
1545	  size_t thread_block_size_ = 0;
1546	  // Product of cluster_dims from block annotation (default 1).
1547	  int cluster_size_ = 1;
1548	  // Stack of per-Block workspace buffers gathered while visiting children
1549	  std::vector<Array<Buffer>> workspace_stack_;
1550	  // Counter and arrive-counts for mbarrier allocation via
1551	  // alloc_mbarrier callback. Used to inject a barrier buffer with
1552	  // barrier_init annotation into the root block after all tile ops are lowered.
1553	  int mbarrier_count_{0};
1554	  std::vector<int> mbarrier_arrive_counts_;
1555	  // The shared.barrier scope buffer created lazily by alloc_mbarrier callback.
1556	  Optional<Buffer> mbarrier_buffer_;
1557	  // Fallback mbarrier parity derived from the nearest enclosing serial loop.
1558	  std::vector<PrimExpr> loop_mbar_phase_stack_;
1559	  // For ptx Node, we need to remap the buffer and indices
1560	  // By access CallNode instead of BufferLoad Node.
1561	  bool is_ptx_{false};
1562	  std::unordered_map<Var, PrimExpr, ObjectPtrHash, ObjectPtrEqual>
1563	      bind_var_to_expr_;
1564	  // Mapping from data Var of a Buffer to Buffer, for lookup
1565	  std::unordered_map<Var, Buffer, ObjectPtrHash, ObjectPtrEqual> buffer_map_;
1566	  Map<Var, Var> var_remap_;
1567	  bool has_tma_{false};
1568	  // Flag to indicate we are inside a TMA context (tma_load, tma_load_im2col,
1569	  // tma_store). When true, HandleAccessPtrAndOffset only updates buffer data
1570	  // without recomputing indices, since swizzle is encoded in TMA descriptor
1571	  // parameters rather than in memory indices.
1572	  bool in_tma_context_{false};
1573	  // Pending barrier arrive-count overrides from multi-TMA cluster copies.
1574	  std::unordered_map<Var, PrimExpr, ObjectPtrHash, ObjectPtrEqual>
1575	      barrier_arrive_updates_;
1576	  // Per-buffer shared-memory alignment requirements (bytes) reported by op
1577	  // lowerings via the require_smem_alignment callback, keyed by the data Var's
1578	  // name hint. Written back as the kSmemAlignmentMap PrimFunc attribute.
1579	  Map<String, IntImm> smem_alignment_map_;
1580	};
1581	
1582	namespace transform {
1583	
1584	using namespace tirx::transform;
1585	
1586	tvm::transform::Pass LowerTileOp() {
1587	  auto pass_func = [=](PrimFunc f, const IRModule &m, const PassContext &ctx) {
1588	    return LowerTileOpPass::Substitute(std::move(f));
1589	  };
1590	  return CreatePrimFuncPass(pass_func, 0, "tl.LowerTileOp", {});
1591	}
1592	
1593	TVM_FFI_STATIC_INIT_BLOCK() {
1594	  namespace refl = reflection;
1595	  refl::GlobalDef().def("tl.transform.LowerTileOp", LowerTileOp);
1596	}
1597	} // namespace transform
